sys_variable_value.value:
(function() {
    var publisher = new x_1295779_conflu_0.ConfluencePublisher();
    var builder = new x_1295779_conflu_0.ContentBuilder();

    // Get the source record
    var sourceGr = new GlideRecord(source_table);
    if (!sourceGr.get(source_record_id)) {
        adf_content = JSON.stringify({ type: 'doc', version: 1, content: [] });
        gs.warn('Build Page Content: Source record not found: ' + source_table + '/' + source_record_id);
        return;
    }

    // Get the publishing definition to determine content strategy
    var definition = publisher._getDefinition(publishing_definition);
    if (!definition) {
        adf_content = JSON.stringify({ type: 'doc', version: 1, content: [] });
        gs.warn('Build Page Content: Definition not found: ' + publishing_definition);
        return;
    }

    var adfDoc;

    if (definition.template_page_id) {
        // TEMPLATE MODE: Fetch template page and resolve placeholders
        var config = publisher._getConnectionConfig(definition.connection_config);
        if (!config || !config.cloud_id) {
            adf_content = JSON.stringify({ type: 'doc', version: 1, content: [] });
            gs.warn('Build Page Content: Connection config not found for template mode');
            return;
        }

        var templateAdf = publisher._fetchTemplateBody(config.cloud_id, definition.template_page_id);
        if (!templateAdf) {
            // Fall back to content blocks if template fetch fails
            gs.warn('Build Page Content: Template fetch failed, falling back to content blocks mode');
            adfDoc = builder.buildDocument(publishing_definition, sourceGr);
        } else {
            // Build block map and resolve template
            var blockMap = builder.buildBlockMap(publishing_definition, sourceGr);
            adfDoc = builder.resolveTemplateDocument(templateAdf, blockMap, sourceGr);
        }
    } else {
        // CONTENT BLOCKS MODE: Assemble blocks sequentially
        adfDoc = builder.buildDocument(publishing_definition, sourceGr);
    }

    adf_content = JSON.stringify(adfDoc);
})();

